const groups={},tests=[];let lines=[];
const test=(name,run)=>tests.push({name,run});
const log=(...args)=>lines.push(args.join(' '));
const pause=()=>new Promise(resolve=>setTimeout(resolve,30));
function next(){return new Promise(resolve=>{function receive(e){removeEventListener('message',receive);resolve(e)}addEventListener('message',receive)})}
async function runTests(){for(const {name,run} of tests){if(CASE&&name!==CASE)continue;lines=[];try{await run()}catch(e){log('ERROR',e.name,e.message)}groups[name]=lines.slice()}return groups}
test('window-copy',async()=>{const x={n:1};x.self=x;const p=next();postMessage(x,'*');x.n=9;const e=await p;log(e.data!==x,e.data.self===e.data,e.data.n,e.source===window,e.origin===location.origin,e.isTrusted,Object.isFrozen(e.ports),e.ports.length)});
test('window-target-origin',async()=>{let n=0;const f=()=>n++;addEventListener('message',f);postMessage('lost','https://other.example');await pause();removeEventListener('message',f);log(n)});
test('window-default',async()=>{const p=next();postMessage(undefined);const e=await p;log(e.data===undefined,e.source===window,e.origin===location.origin)});
test('window-options',async()=>{const order=[],p=next();postMessage({get n(){order.push('data');return 1}},{get targetOrigin(){order.push('origin');return '*'},get transfer(){order.push('transfer');return []}});order.push('return');const e=await p;order.push('message');log(order.join(','),e.data.n)});
test('window-invalid-origin',async()=>{for(const origin of ['invalid','https://[','null']){let reads=0;try{postMessage({get n(){reads++;return 1}},origin);log('accepted',reads)}catch(e){log(e.name,reads)}}});
test('window-buffer-transfer',async()=>{const b=new ArrayBuffer(3),v=new Uint8Array(b);v[1]=7;const p=next();postMessage({b,v},'*',[b]);log('detached',b.byteLength);const e=await p;log(e.data.b!==b,e.data.b===e.data.v.buffer,e.data.v[1])});
test('window-wrong-origin-transfer',async()=>{const b=new ArrayBuffer(3);let n=0;const f=()=>n++;addEventListener('message',f);postMessage(b,'https://other.example',[b]);log('detached',b.byteLength);await pause();removeEventListener('message',f);log(n)});
test('window-errors',async()=>{for(const f of [()=>postMessage(),()=>postMessage.call({},1,'*'),()=>postMessage(()=>{},'*'),()=>postMessage({},Symbol()),()=>postMessage({},'*',[{}])]){try{f();log('accepted')}catch(e){log(e.name)}}});
test('window-overloads',async()=>{const values=[['undefined',undefined],['null',null],['false',false],['zero',0],['string','*'],['boxed',new String('*')],['array',[]],['function',()=>{}]];for(const [label,value] of values)for(const n of [2,3]){const order=[];let count=0;const f=()=>count++;addEventListener('message',f);try{if(n===2)postMessage({get x(){order.push('data');return 1}},value);else postMessage({get x(){order.push('data');return 1}},value,[]);log(label,n,'ok',order.join(','))}catch(e){log(label,n,e.name,order.join(','))}await pause();removeEventListener('message',f);log('received',count)}});
test('window-receivers',async()=>{for(const [label,value] of [['undefined',undefined],['null',null],['window',window],['document',document],['proxy',new Proxy(window,{})],['number',0]])try{postMessage.call(value,'go','*');log(label,'ok')}catch(e){log(label,e.name)}await pause();log('metadata',postMessage.name,postMessage.length,Object.hasOwn(postMessage,'prototype'))});
test('window-port-transfer',async()=>{const c=new MessageChannel(),p=next();postMessage({port:c.port2},'*',[c.port2]);const e=await p;log(e.data.port!==c.port2,e.ports.length,e.data.port===e.ports[0],Object.isFrozen(e.ports));const received=new Promise(resolve=>c.port1.onmessage=e=>resolve(e.data));e.ports[0].postMessage('reply');log(await received)});
test('window-listener-microtasks',async()=>{let flag=false;const p=new Promise(resolve=>{function first(){removeEventListener('message',first);Promise.resolve().then(()=>flag=true)}function second(e){removeEventListener('message',second);log(flag,e.currentTarget===window,e.eventPhase);resolve(e)}addEventListener('message',first);addEventListener('message',second)});postMessage('go','*');const e=await p;log('during',e.currentTarget===window);await pause();log('after',e.currentTarget===null)});
test('window-private-factories',async()=>{let calls=0;const old=MessageEvent,oldJSON=JSON.stringify,oldDispatch=window.dispatchEvent;MessageEvent=function(){calls++;throw Error('public constructor')};JSON.stringify=()=>{calls++;throw Error('public JSON')};window.dispatchEvent=()=>{calls++;throw Error('public dispatch')};try{const p=next();postMessage({n:1},'*');const e=await p;log(e instanceof old,e.data.n,calls)}finally{MessageEvent=old;JSON.stringify=oldJSON;window.dispatchEvent=oldDispatch}});
test('window-origin-canonical',async()=>{for(const target of [location.origin+'/',location.origin.toUpperCase()+'/path?query#fragment','/','*']){const p=next();postMessage(target,target);const e=await p;log(e.data===target,e.origin===location.origin)}let count=0;const f=()=>count++;addEventListener('message',f);postMessage('lost','data:text/plain,hello');await pause();removeEventListener('message',f);log('opaque',count)});
test('window-private-iterator-symbol',async()=>{const old=Symbol,c=new MessageChannel(),b=new ArrayBuffer(2);try{globalThis.Symbol=undefined;const copy=structuredClone({n:1},{transfer:[b]});log(copy.n,b.byteLength);log(new MessageEvent('message',{ports:[c.port1]}).ports[0]===c.port1);const p=next();postMessage({port:c.port2},'*',[c.port2]);const e=await p;log(e.ports[0]===e.data.port);const received=new Promise(resolve=>c.port1.onmessage=e=>resolve(e.data));e.data.port.postMessage('reply',[]);log(await received)}finally{globalThis.Symbol=old}});
test('window-transfer-validation',()=>{for(const run of [()=>postMessage('go','*',null),()=>postMessage('go',{transfer:null}),()=>postMessage('go','*',[{}]),()=>postMessage('go',{transfer:[{}],targetOrigin:'invalid'})])try{run();log('accepted')}catch(e){log(e.name)}const b=new ArrayBuffer(2);try{postMessage({get x(){log('data getter');return 1}},'invalid',[b,b])}catch(e){log(e.name,b.byteLength)}});
